import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int m = Integer.parseInt(st.nextToken()); boolean[] finished = new boolean[n + 1]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < m; i++) { finished[Integer.parseInt(st.nextToken())] = true; } List<Integer> chef = new ArrayList<>(); List<Integer> assistant = new ArrayList<>(); boolean chefTurn = true; for (int i = 1; i <= n; i++) { if (!finished[i]) { if (chefTurn) { chef.add(i); } else { assistant.add(i); } chefTurn = !chefTurn; } } printList(out, chef); printList(out, assistant); } out.flush(); out.close(); } private static void printList(PrintWriter out, List<Integer> list) { if (list.isEmpty()) { out.println(); } else { for (int i = 0; i < list.size(); i++) { out.print(list.get(i) + (i == list.size() - 1 ? "" : " ")); } out.println(); } } }